<?php
require "includes/db.php";if(session_status()===PHP_SESSION_NONE)session_start();$pageTitle="Cart | Artisan Brew Co.";
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['update']))foreach($_POST['qty'] as $id=>$q){$q=(int)$q;if($q<1)unset($_SESSION['cart'][(int)$id]);else$_SESSION['cart'][(int)$id]=$q;}if(isset($_POST['clear']))$_SESSION['cart']=[];}
$items=[];$total=0;$ids=array_keys($_SESSION['cart']??[]);
if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));$types=str_repeat('i',count($ids));$s=$conn->prepare("SELECT * FROM products WHERE product_id IN ($ph)");$s->bind_param($types,...$ids);$s->execute();$r=$s->get_result();while($p=$r->fetch_assoc()){$p['qty']=$_SESSION['cart'][$p['product_id']];$p['line']=$p['qty']*$p['price'];$total+=$p['line'];$items[]=$p;}}
require "includes/header.php";?>
<section class="page-hero"><p class="eyebrow">YOUR ORDER</p><h1>Shopping <em>Cart.</em></h1></section><section class="section cart-section">
<?php if(!$items):?><div class="empty"><h2>Your cart is empty.</h2><p class="muted">Add a coffee from our collection to get started.</p><a class="btn dark" href="products.php">Browse Coffee</a></div><?php else:?><form method="post"><div class="cart-table"><?php foreach($items as $p):?><div class="cart-row"><img src="assets/images/<?=htmlspecialchars($p['image'])?>" alt=""><div><h3><?=htmlspecialchars($p['name'])?></h3><small>$<?=number_format($p['price'],2)?> each</small></div><input type="number" name="qty[<?=$p['product_id']?>]" min="1" value="<?=$p['qty']?>"><strong>$<?=number_format($p['line'],2)?></strong></div><?php endforeach;?></div><div class="cart-total"><span>Total</span><strong>$<?=number_format($total,2)?></strong></div><div class="cart-actions"><button class="btn outline" name="update">Update Cart</button><button class="btn outline" name="clear">Clear Cart</button><a class="btn dark" href="checkout.php">Checkout</a></div></form><?php endif;?></section><?php require "includes/footer.php";?>